// Extracts the few file-type icons the Code tab uses from the Material Icon Theme
// set (@iconify-json/material-icon-theme, MIT) into src/fileIconData.js, so the
// app ships ~60 small SVGs instead of the whole 1200-icon set.
//
//   node scripts/gen-file-icons.mjs
//
// Re-run after changing the icon keys in src/fileTypes.js. The generated file is
// committed: the icon package is only a dev dependency.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { ALL_ICON_KEYS } from '../src/fileTypes.js'

const root = fileURLToPath(new URL('..', import.meta.url))
const set = JSON.parse(readFileSync(`${root}node_modules/@iconify-json/material-icon-theme/icons.json`, 'utf8'))

function resolve(name) {
  let icon = set.icons[name]
  let seen = 0
  while (!icon && set.aliases?.[name] && seen++ < 5) {
    name = set.aliases[name].parent
    icon = set.icons[name]
  }
  return icon
}

// Gradients/clip paths carry ids; inline SVGs share one document, so two icons
// with the same id ("a") would pick each other's gradient. Prefix them.
function scopeIds(body, key) {
  const ids = [...body.matchAll(/\bid="([^"]+)"/g)].map((m) => m[1])
  let out = body
  for (const id of ids) {
    const next = `fi-${key}-${id}`
    out = out.replaceAll(`id="${id}"`, `id="${next}"`).replaceAll(`url(#${id})`, `url(#${next})`).replaceAll(`href="#${id}"`, `href="#${next}"`)
  }
  return out
}

const data = {}
const missing = []
for (const key of ALL_ICON_KEYS) {
  const icon = resolve(key)
  if (!icon) {
    missing.push(key)
    continue
  }
  const w = icon.width ?? set.width ?? 16
  const h = icon.height ?? set.height ?? 16
  if (w !== h) throw new Error(`${key} is ${w}x${h}, expected a square icon`)
  const left = icon.left ?? set.left ?? 0
  const top = icon.top ?? set.top ?? 0
  data[key] = { viewBox: `${left} ${top} ${w} ${h}`, body: scopeIds(icon.body, key) }
}
if (missing.length) throw new Error(`Icons not found in the set: ${missing.join(', ')}`)

const header =
  '// Generated by scripts/gen-file-icons.mjs from @iconify-json/material-icon-theme (MIT, Material Icon Theme).\n' +
  '// Do not edit by hand. Each icon: { viewBox, body (SVG markup) }.\n\n'
writeFileSync(
  `${root}src/fileIconData.js`,
  `${header}export const FILE_ICONS = ${JSON.stringify(data, null, 1)}\n`,
)
console.log(`file icons: ${Object.keys(data).length} written to src/fileIconData.js`)
